/**
 * The mark for a provider id, or `undefined` when none is known.
 *
 * Matched the way {@link providerDisplayName} matches, on a trimmed
 * lower-cased id, because an id reaches the dashboard from a catalog row, a
 * stored credential and a model selector's prefix, and those do not agree on
 * case.
 */
export function providerMark(
  providerId: string,
): ProviderMarkGlyph | undefined {
  // `Object.hasOwn` rather than a bare index: an id here is an operator-chosen
  // instance name and the config rejects only ":" and "/", so `constructor` and
  // `toString` are legal names. A bare index resolves those off the prototype
  // and hands back a function, which the caller then reads `.shapes` from.
  const key = providerId.trim().toLowerCase()
  return Object.hasOwn(PROVIDER_MARKS, key) ? PROVIDER_MARKS[key] : undefined
}

/**
 * Each model maker's mark, keyed on the vendor slug the catalog id carries.
 *
 * A second key space rather than a second name for the first, because the two
 * disagree on the same companies: the maker `Mistral AI` slugs to `mistralai`
 * where the provider id is `mistral`, `Z.ai` to `z-ai` against `zai`, and
 * `Moonshot AI` to `moonshotai` against `moonshot`. One table would miss all
 * three. The glyphs are shared; only the keys differ.
 *
 * The vocabulary is closed: a model's vendor is voted from `_ORG_VENDORS` and
 * `_KEY_VENDORS` in `services/model_identity.py` and from nowhere else, so a
 * new maker is a change in this repository rather than a dataset refresh.
 *
 * Amazon is deliberately absent. Its mark in the source set is the aws
 * wordmark, which is unreadable at 14px, so it tiles like the Bedrock and
 * SageMaker rows it shares a vendor with.
 */
const MAKER_MARKS: Readonly<Record<string, ProviderMarkGlyph>> = {
  ai21: GLYPH_AI21,
  alibaba: GLYPH_ALIBABA,
  anthropic: GLYPH_ANTHROPIC,
  bytedance: GLYPH_BYTEDANCE,
  cohere: GLYPH_COHERE,
  deepseek: GLYPH_DEEPSEEK,
  google: GLYPH_GOOGLE,
  meta: GLYPH_META,
  microsoft: GLYPH_MICROSOFT,
  minimax: GLYPH_MINIMAX,
  mistralai: GLYPH_MISTRAL,
  moonshotai: GLYPH_MOONSHOT,
  nousresearch: GLYPH_NOUSRESEARCH,
  nvidia: GLYPH_NVIDIA,
  openai: GLYPH_OPENAI,
  perplexity: GLYPH_PERPLEXITY,
  xai: GLYPH_XAI,
  "z-ai": GLYPH_ZAI,
}

/**
 * The mark for a model maker, by the vendor slug, or `undefined` when none is
 * known.
 *
 * The slug is taken from the catalog id rather than recomputed from the vendor
 * string: the gateway builds that id as `vendor_slug(vendor)/slug`, so the
 * prefix already is the answer, and mirroring the Python normalization here
 * would be a second implementation to drift.
 */
export function makerMark(vendorSlug: string): ProviderMarkGlyph | undefined {
  // Guarded like `providerMark`, for the same reason.
  const key = vendorSlug.trim().toLowerCase()
  return Object.hasOwn(MAKER_MARKS, key) ? MAKER_MARKS[key] : undefined
}

/**
 * The tables' own keys, for the drift gate beside `brandMarkKeys`.
 *
 * Exported for that comparison only. The app asks `hasProviderMark` and
 * `hasMakerMark`, which answer from the synchronous key lists rather than from
 * here, so that a page can decide its slots without fetching the geometry.
 */
export const MARK_TABLE_KEYS_FOR_TEST = {
  providers: Object.keys(PROVIDER_MARKS),
  makers: Object.keys(MAKER_MARKS),
}
